"use client";

import { useState, useEffect, useCallback } from "react";
import Link from "next/link";
import { Menu, X } from "lucide-react";
import { WordMark } from "@/components/ui/WordMark";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

const NAV_LINKS = [
  { label: "Explore", href: "#explore" },
  { label: "Saved",   href: "#saved"   },
] as const;

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  const handleScroll = useCallback(() => {
    setScrolled(window.scrollY > 4);
  }, []);

  useEffect(() => {
    window.addEventListener("scroll", handleScroll, { passive: true });
    handleScroll();
    return () => window.removeEventListener("scroll", handleScroll);
  }, [handleScroll]);

  useEffect(() => {
    const mq = window.matchMedia("(min-width: 768px)");
    const handler = (e: MediaQueryListEvent) => { if (e.matches) setMenuOpen(false); };
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);

  const closeMenu = () => setMenuOpen(false);

  return (
    <>
      <header className={cn("sticky top-0 z-50 h-16 border-b border-slate-200 glass transition-shadow duration-200", scrolled && "shadow-[0_2px_8px_rgba(15,23,42,0.07)]")}>
        <div className="mx-auto flex h-full max-w-[1200px] items-center gap-8 px-6">
          <Link href="/" aria-label="InternAtlas home" onClick={closeMenu}>
            <WordMark />
          </Link>
          <nav aria-label="Primary navigation" className="hidden flex-1 md:flex items-center gap-1">
            {NAV_LINKS.map((link) => (
              <Link key={link.href} href={link.href} className="rounded-lg px-3.5 py-1.5 text-[14px] font-medium text-slate-600 transition-colors hover:bg-slate-100 hover:text-slate-900">
                {link.label}
              </Link>
            ))}
          </nav>
          <div className="ml-auto hidden items-center gap-2.5 md:flex">
            <Button variant="ghost" size="sm" asChild>
              <Link href="#login">Log in</Link>
            </Button>
            <Button size="sm" asChild>
              <Link href="#signup">
                Get Started <span className="ml-0.5 transition-transform group-hover:translate-x-0.5">→</span>
              </Link>
            </Button>
          </div>
          <button className="ml-auto flex h-8 w-8 items-center justify-center rounded-lg text-slate-600 transition-colors hover:bg-slate-100 md:hidden" aria-label={menuOpen ? "Close menu" : "Open menu"} aria-expanded={menuOpen} onClick={() => setMenuOpen((v) => !v)}>
            {menuOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>
      </header>
      <div className={cn("fixed inset-x-0 top-16 z-40 border-b border-slate-200 bg-white px-6 pb-6 shadow-lg md:hidden transition-all duration-300 ease-out", menuOpen ? "translate-y-0 opacity-100 pointer-events-auto" : "-translate-y-3 opacity-0 pointer-events-none")} aria-hidden={!menuOpen}>
        <nav className="mb-4 flex flex-col" aria-label="Mobile navigation">
          {NAV_LINKS.map((link) => (
            <Link key={link.href} href={link.href} onClick={closeMenu} className="border-b border-slate-100 py-3.5 text-base font-medium text-slate-700 transition-colors hover:text-slate-900">
              {link.label}
            </Link>
          ))}
        </nav>
        <div className="flex flex-col gap-2.5">
          <Button variant="ghost" className="w-full justify-center" asChild>
            <Link href="#login" onClick={closeMenu}>Log in</Link>
          </Button>
          <Button className="w-full justify-center" asChild>
            <Link href="#signup" onClick={closeMenu}>Get Started →</Link>
          </Button>
        </div>
      </div>
    </>
  );
}
